private void remove(
    NavigableMap<Interval, TimelineEntry> timeline,
    Interval interval,
    boolean incompleteOk
)
{
  timeline.remove(interval);

  for (Entry<Interval, TreeMap<VersionType, TimelineEntry>> versionEntry : allTimelineEntries.entrySet()) {
    if (versionEntry.getKey().overlap(interval) != null) {
      if (incompleteOk) {
        add(timeline, versionEntry.getKey(), versionEntry.getValue().lastEntry().getValue());
      } else {
        for (VersionType ver : versionEntry.getValue().descendingKeySet()) {
          TimelineEntry timelineEntry = versionEntry.getValue().get(ver);
          if (timelineEntry.getPartitionHolder().isComplete()) {
            add(timeline, versionEntry.getKey(), timelineEntry);
            break;
          }
        }
      }
    }
  }
}

@GuardedBy("lock")
private List<TimelineObjectHolder<VersionType, ObjectType>> lookup(Interval interval, Partitions completeness)
{
  List<TimelineObjectHolder<VersionType, ObjectType>> retVal = new ArrayList<>();
  NavigableMap<Interval, TimelineEntry> timeline;
  if (completeness == Partitions.INCOMPLETE_OK) {
    timeline = incompletePartitionsTimeline;
  } else {
    timeline = completePartitionsTimeline;
  }

  final long queryStartMillis = interval.getStartMillis();
  final long queryEndMillis = interval.getEndMillis();
  final boolean queryIsEmpty = Intervals.isEmpty(interval);
  final boolean queryIsEternity = Intervals.isEternity(interval);
  final boolean queryEndpointsComparable = Intervals.canCompareEndpointsAsStrings(interval);
  final DateTime queryStart = interval.getStart();
  final DateTime queryEnd = interval.getEnd();
  final int queryComparedToEternity = Comparators.intervalsByStartThenEnd().compare(interval, Intervals.ETERNITY);
  final boolean queryMatchesEternity = queryComparedToEternity == 0;
  final boolean queryCoversEternity = queryIsEternity || queryMatchesEternity;

  for (Entry<Interval, TimelineEntry> entry : timeline.entrySet()) {
    Interval timelineInterval = entry.getKey();
    TimelineEntry val = entry.getValue();
    final Interval trueInterval = val.getTrueInterval();
    final VersionType version = val.getVersion();
    final long timelineStartMillis = timelineInterval.getStartMillis();
    final long timelineEndMillis = timelineInterval.getEndMillis();
    final boolean timelineIsEmpty = Intervals.isEmpty(timelineInterval);
    final boolean timelineIsEternity = Intervals.isEternity(timelineInterval);
    final boolean timelineEndpointsComparable = Intervals.canCompareEndpointsAsStrings(timelineInterval);
    final int timelineOrder = Comparators.intervalsByStartThenEnd().compare(timelineInterval, interval);
    final boolean completelyBeforeQuery = timelineEndMillis <= queryStartMillis;
    final boolean completelyAfterQuery = timelineStartMillis >= queryEndMillis;
    final boolean timelineContainsQuery =
        timelineStartMillis <= queryStartMillis && timelineEndMillis >= queryEndMillis;
    final boolean queryContainsTimeline =
        queryStartMillis <= timelineStartMillis && queryEndMillis >= timelineEndMillis;
    final boolean leftOverlap =
        timelineStartMillis < queryStartMillis && timelineEndMillis < queryEndMillis;
    final boolean rightOverlap =
        timelineStartMillis > queryStartMillis && timelineEndMillis > queryEndMillis;
    boolean overlapsQuery = false;

    if (queryEndpointsComparable && timelineEndpointsComparable) {
      if (completelyBeforeQuery) {
        overlapsQuery = false;
      } else if (completelyAfterQuery) {
        overlapsQuery = false;
      } else if (timelineOrder == 0) {
        overlapsQuery = !timelineIsEmpty && !queryIsEmpty;
      } else if (queryIsEmpty) {
        if (timelineIsEmpty) {
          overlapsQuery = false;
        } else if (timelineStartMillis < queryEndMillis) {
          if (queryStartMillis < timelineEndMillis) {
            overlapsQuery = true;
          } else {
            overlapsQuery = false;
          }
        } else {
          overlapsQuery = false;
        }
      } else if (timelineIsEmpty) {
        if (queryStartMillis < timelineEndMillis) {
          if (timelineStartMillis < queryEndMillis) {
            overlapsQuery = true;
          } else {
            overlapsQuery = false;
          }
        } else {
          overlapsQuery = false;
        }
      } else if (timelineContainsQuery) {
        overlapsQuery = queryStartMillis < queryEndMillis;
      } else if (queryContainsTimeline) {
        overlapsQuery = timelineStartMillis < timelineEndMillis;
      } else if (leftOverlap) {
        if (queryStartMillis < timelineEndMillis) {
          if (timelineStartMillis < queryEndMillis) {
            overlapsQuery = true;
          } else {
            overlapsQuery = false;
          }
        } else {
          overlapsQuery = false;
        }
      } else if (rightOverlap) {
        if (timelineStartMillis < queryEndMillis) {
          if (queryStartMillis < timelineEndMillis) {
            overlapsQuery = true;
          } else {
            overlapsQuery = false;
          }
        } else {
          overlapsQuery = false;
        }
      } else {
        overlapsQuery = timelineStartMillis < queryEndMillis && queryStartMillis < timelineEndMillis;
      }

      if (overlapsQuery) {
        boolean holderHasData = false;
        PartitionHolder<ObjectType> partitionHolder = val.getPartitionHolder();
        if (partitionHolder != null) {
          if (!partitionHolder.isEmpty()) {
            for (PartitionChunk<ObjectType> chunk : partitionHolder) {
              ObjectType payload = chunk.getObject();
              if (payload instanceof DataSegment) {
                DataSegment segment = (DataSegment) payload;
                ShardSpec shardSpec = segment.getShardSpec();
                if (shardSpec != null) {
                  boolean tombstone = ShardSpec.Type.TOMBSTONE.equals(shardSpec.getType());
                  holderHasData = holderHasData || (!tombstone && segment.hasData());
                } else {
                  holderHasData = holderHasData || segment.hasData();
                }
              } else if (payload.hasData()) {
                holderHasData = true;
              }
              if (holderHasData) {
                break;
              }
            }
          }
        }
        if (!(skipObjectsWithNoData && !holderHasData)) {
          PartitionHolder<ObjectType> visibleChunks = PartitionHolder.copyWithOnlyVisibleChunks(partitionHolder);
          TimelineObjectHolder<VersionType, ObjectType> visibleHolder = new TimelineObjectHolder<>(
              timelineInterval,
              trueInterval,
              version,
              visibleChunks
          );
          retVal.add(visibleHolder);
        }
      }
    } else if (queryCoversEternity || timelineIsEternity) {
      overlapsQuery = timelineStartMillis < queryEndMillis && queryStartMillis < timelineEndMillis;
      if (overlapsQuery) {
        boolean holderHasData = val.getPartitionHolder().hasData();
        if (!(skipObjectsWithNoData && !holderHasData)) {
          PartitionHolder<ObjectType> visibleChunks =
              PartitionHolder.copyWithOnlyVisibleChunks(val.getPartitionHolder());
          TimelineObjectHolder<VersionType, ObjectType> visibleHolder = new TimelineObjectHolder<>(
              timelineInterval,
              trueInterval,
              version,
              visibleChunks
          );
          retVal.add(visibleHolder);
        }
      }
    } else {
      Interval foundOverlap = Intervals.findOverlappingInterval(interval, new Interval[]{timelineInterval});
      if (foundOverlap != null) {
        overlapsQuery = true;
      } else {
        overlapsQuery = timelineStartMillis < queryEndMillis && queryStartMillis < timelineEndMillis;
      }
      if (overlapsQuery) {
        boolean holderHasData = val.getPartitionHolder().hasData();
        if (!(skipObjectsWithNoData && !holderHasData)) {
          PartitionHolder<ObjectType> visibleChunks =
              PartitionHolder.copyWithOnlyVisibleChunks(val.getPartitionHolder());
          TimelineObjectHolder<VersionType, ObjectType> visibleHolder = new TimelineObjectHolder<>(
              timelineInterval,
              trueInterval,
              version,
              visibleChunks
          );
          retVal.add(visibleHolder);
        }
      }
    }
  }

  if (retVal.isEmpty()) {
    return retVal;
  }

  TimelineObjectHolder<VersionType, ObjectType> firstEntry = retVal.get(0);
  Interval firstInterval = firstEntry.getInterval();
  final long firstStartMillis = firstInterval.getStartMillis();
  final long firstEndMillis = firstInterval.getEndMillis();
  final boolean firstIsEmpty = Intervals.isEmpty(firstInterval);
  final boolean firstIsEternity = Intervals.isEternity(firstInterval);
  boolean firstOverlapsQuery;
  if (queryIsEternity || firstIsEternity) {
    firstOverlapsQuery = queryStartMillis < firstEndMillis && firstStartMillis < queryEndMillis;
  } else if (queryIsEmpty && firstIsEmpty) {
    firstOverlapsQuery = false;
  } else if (firstEndMillis <= queryStartMillis) {
    firstOverlapsQuery = false;
  } else if (firstStartMillis >= queryEndMillis) {
    firstOverlapsQuery = false;
  } else {
    firstOverlapsQuery = queryStartMillis < firstEndMillis && firstStartMillis < queryEndMillis;
  }
  if (firstOverlapsQuery) {
    if (queryStart.isAfter(firstInterval.getStart())) {
      Interval trimmedFirst = new Interval(queryStart, firstInterval.getEnd());
      retVal.set(
          0,
          new TimelineObjectHolder<>(
              trimmedFirst,
              firstEntry.getTrueInterval(),
              firstEntry.getVersion(),
              firstEntry.getObject()
          )
      );
    }
  }

  TimelineObjectHolder<VersionType, ObjectType> lastEntry = retVal.get(retVal.size() - 1);
  Interval lastInterval = lastEntry.getInterval();
  final long lastStartMillis = lastInterval.getStartMillis();
  final long lastEndMillis = lastInterval.getEndMillis();
  final boolean lastIsEmpty = Intervals.isEmpty(lastInterval);
  final boolean lastIsEternity = Intervals.isEternity(lastInterval);
  boolean lastOverlapsQuery;
  if (queryIsEternity || lastIsEternity) {
    lastOverlapsQuery = queryStartMillis < lastEndMillis && lastStartMillis < queryEndMillis;
  } else if (queryIsEmpty && lastIsEmpty) {
    lastOverlapsQuery = false;
  } else if (lastEndMillis <= queryStartMillis) {
    lastOverlapsQuery = false;
  } else if (lastStartMillis >= queryEndMillis) {
    lastOverlapsQuery = false;
  } else {
    lastOverlapsQuery = queryStartMillis < lastEndMillis && lastStartMillis < queryEndMillis;
  }
  if (lastOverlapsQuery) {
    if (queryEnd.isBefore(lastInterval.getEnd())) {
      Interval trimmedLast = new Interval(lastInterval.getStart(), queryEnd);
      retVal.set(
          retVal.size() - 1,
          new TimelineObjectHolder<>(
              trimmedLast,
              lastEntry.getTrueInterval(),
              lastEntry.getVersion(),
              lastEntry.getObject()
          )
      );

      ),
      timeline.lookup(Intervals.of("2011-01-01/2011-01-20"))
  );
}

